python3 - <<'PY'
import re
p="prototypes/p8-search-words.html"
s=open(p).read()
new_hl=r'''function hl(s){ s=esc(s); const T=terms(); if(!T.length) return s;
  const esc2=t=>t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
  const pat=T.map(esc2).sort((a,b)=>b.length-a.length).join('|');
  return s.replace(new RegExp('('+pat+')','ig'),'<mark>$1</mark>'); }

function render'''
s2=re.sub(r"function hl\(s\)\{.*?\nfunction render", lambda m: new_hl, s, count=1, flags=re.S)
assert s2!=s, "no substitution"
open(p,"w").write(s2)
js=re.search(r"<script>(.*)</script>", s2, re.S).group(1)
open("/tmp/p8.js","w").write(js)
print("hl lines:")
for l in s2.splitlines():
    if "esc2" in l: print(l)
PY
