const items=[
 {url:"https://wikipedia.org/wiki/Sourdough",title:"Sourdough — Wikipedia",desc:"Bread by fermentation of dough.",note:"24h cold-proof for extra tang."},
 {url:"https://seriouseats.com/pizza-dough",title:"The Best Pizza Dough",desc:"A cold-ferment dough for blistered crust.",note:""},
 {url:"https://nytimes.com/2026/travel/kyoto",title:"36 Hours in Kyoto",desc:"Temples at dawn and quiet streets.",note:"Book a ryokan early — they fill up."},
];
let q="";
function terms(){const out=[];const re=/"([^"]+)"|(\S+)/g;let m;while((m=re.exec(q))!==null){const t=(m[1]||m[2]).toLowerCase().trim();if(t)out.push(t);}return out;}
function fields(it){return{title:it.title,desc:it.desc||"",note:it.note||"",url:it.url};}
function matchAll(it){const T=terms();if(!T.length)return true;const f=fields(it);const hay=(f.title+" "+f.desc+" "+f.note+" "+f.url).toLowerCase();return T.every(t=>hay.includes(t));}
function run(query){q=query;return items.filter(matchAll).map(i=>i.title);}
