console.log("pizza dough ->", run("pizza dough"));
console.log("kyoto temple ->", run("kyoto temple"));
console.log("ryokan ->", run("ryokan"));
console.log("\"36 hours\" ->", run("\"36 hours\""));
console.log("\"pizza sourdough\" (exact, should be none) ->", run("\"pizza sourdough\""));
'

