// Service worker: the one piece with permission to reach other websites, so it
// fetches a page's name/description on the library's behalf (DD-002, option A).
// Best-effort (SCN-004): on any failure it reports "not readable" and the link
// is still saved with a fallback name.

import { parseMetadata } from './src/metadata.js';

async function fetchMeta(url) {
  try {
    const res = await fetch(url, { redirect: 'follow', credentials: 'omit' });
    if (!res.ok) return { ok: false, error: 'status ' + res.status };
    const ctype = res.headers.get('content-type') || '';
    if (ctype.includes('application/pdf')) {
      // A PDF has no HTML title; treat as readable-by-kind (SCN-017 groundwork).
      return { ok: true, title: '', description: '', kind: 'pdf' };
    }
    const html = await res.text();
    const meta = parseMetadata(html);
    return { ok: meta.ok, title: meta.title, description: meta.description, kind: 'web' };
  } catch (e) {
    return { ok: false, error: String(e) };
  }
}

chrome.runtime.onMessage.addListener((msg, _sender, reply) => {
  if (msg && msg.type === 'fetchMeta' && msg.url) {
    fetchMeta(msg.url).then(reply);
    return true; // async response
  }
  return false;
});

