// Library UI — the core spine (SCN-001,002,003,004; plus SCN-022 guard).
// Talks to the local DB (db.js) and asks the background worker to read a page's
// name (background.js). Degrades gracefully if opened outside the extension.

import { normalizeUrl, toFullUrl, hostOf, isProbablyUrl, findDuplicate, makeLink } from './src/core.js';
import { allLinks, putLink, findByNorm } from './src/db.js';

const $ = (id) => document.getElementById(id);
const input = $('url'), btn = $('save'), listEl = $('list'), countEl = $('count'), flash = $('flash');

let items = []; // in-memory mirror of the DB, newest first

function newestFirst(a, b) { return (b.savedAt || 0) - (a.savedAt || 0); }

async function refresh(freshUrl, pulseNorm) {
  items = (await allLinks()).sort(newestFirst);
  render(freshUrl, pulseNorm);
}

function favLetter(u) { const h = hostOf(u); return (h[0] || '•').toUpperCase(); }

function cardHtml(it, cls) {
  const titleLine = it.unreadable
    ? `${hostOf(it.url)}<span class="ext">· couldn't read the page name</span>`
    : `${escapeHtml(it.title)}<span class="ext">↗ open</span>`;
  const desc = it.unreadable
    ? `<p class="desc faded">We couldn't read this page's name. It's saved and will still open — you can rename it later.</p>`
    : (it.description ? `<p class="desc">${escapeHtml(it.description)}</p>` : '');
  return `<li class="card ${cls || ''}" data-url="${escapeAttr(it.url)}">
    <p class="title">${titleLine}</p>${desc}
    <div class="url"><span class="fav">${favLetter(it.url)}</span>${escapeHtml(hostOf(it.url))}</div>
  </li>`;
}

function render(freshUrl, pulseNorm, loadingUrl) {
  const rows = [];
  if (loadingUrl) {
    rows.push(`<li class="card fresh"><p class="loading">Reading the page to get its name…</p>
      <div class="url"><span class="fav">${favLetter(loadingUrl)}</span>${escapeHtml(hostOf(loadingUrl))}</div></li>`);
  }
  for (const it of items) {
    const cls = it.url === freshUrl ? 'fresh' : (it.norm === pulseNorm ? 'pulse' : '');
    rows.push(cardHtml(it, cls));
  }
  countEl.textContent = items.length ? `${items.length} link${items.length > 1 ? 's' : ''}` : '';
  listEl.innerHTML = items.length || loadingUrl
    ? rows.join('')
    : `<div class="empty"><div class="art">📚</div><h2>Your library starts here</h2>
        <div>Paste your first link in the box above — it'll fetch the page's name for you.</div></div>`;
  for (const el of listEl.querySelectorAll('.card[data-url]')) {
    el.addEventListener('click', () => openLink(el.dataset.url));
  }
  if (pulseNorm) {
    const el = [...listEl.querySelectorAll('.card')].find((c) => c.classList.contains('pulse'));
    if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
  }
}

function openLink(url) {
  const full = toFullUrl(url);
  if (typeof chrome !== 'undefined' && chrome.tabs && chrome.tabs.create) chrome.tabs.create({ url: full });
  else window.open(full, '_blank'); // SCN-002: real page, new tab, library stays put
}

// Ask the background worker to read the page; fall back to "not readable" if it
// isn't reachable or we're running outside the extension (SCN-004 best-effort).
function fetchMeta(url) {
  return new Promise((resolve) => {
    if (typeof chrome !== 'undefined' && chrome.runtime && chrome.runtime.sendMessage) {
      try {
        chrome.runtime.sendMessage({ type: 'fetchMeta', url: toFullUrl(url) }, (resp) => {
          if (chrome.runtime.lastError || !resp) resolve({ ok: false });
          else resolve(resp);
        });
        return;
      } catch { /* fall through */ }
    }
    resolve({ ok: false });
  });
}

function showFlash(msg) { flash.textContent = msg; flash.classList.add('show'); }
function hideFlash() { flash.classList.remove('show'); }

async function save() {
  const raw = input.value.trim();
  if (!raw) return;

  if (!isProbablyUrl(raw)) { // SCN-022
    input.classList.add('bad');
    showFlash(`That doesn't look like a web address — nothing was saved. Check it and try again.`);
    return;
  }
  input.classList.remove('bad');

  const dup = await findByNorm(normalizeUrl(raw)); // SCN-003
  if (dup) {
    input.value = ''; btn.disabled = true;
    showFlash('You already saved this one — here it is. (No duplicate was made.)');
    await refresh(null, dup.norm);
    return;
  }

  hideFlash();
  const url = toFullUrl(raw);
  input.value = ''; btn.disabled = true;
  render(null, null, url); // optimistic "reading…" state

  const meta = await fetchMeta(url);
  const link = makeLink(url, meta, Date.now()); // SCN-001; savedAt = real time
  await putLink(link);
  await refresh(url);
}

function escapeHtml(s) { return String(s || '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c])); }
function escapeAttr(s) { return escapeHtml(s).replace(/"/g, '&quot;'); }

input.addEventListener('input', () => { btn.disabled = input.value.trim().length < 4; input.classList.remove('bad'); if (flash.classList.contains('show')) hideFlash(); });
btn.addEventListener('click', save);
input.addEventListener('keydown', (e) => { if (e.key === 'Enter') save(); });

refresh();

