// "Save this page" — the one-click capture from the page the client is reading
// (DD-002 option A: the add-on can see the current tab, so the name is taken
// straight from it — the most reliable recognise there is). SCN-001 + SCN-003.

import { normalizeUrl, toFullUrl, hostOf, makeLink } from './src/core.js';
import { findByNorm, putLink } from './src/db.js';

const $ = (id) => document.getElementById(id);
let tab = null;

async function init() {
  const [active] = await chrome.tabs.query({ active: true, currentWindow: true });
  tab = active;
  const savable = tab && tab.url && /^https?:\/\//i.test(tab.url);
  $('t').textContent = savable ? (tab.title || hostOf(tab.url)) : 'This page can’t be saved';
  $('h').textContent = savable ? hostOf(tab.url) : '';
  $('save').disabled = !savable;
}

$('save').addEventListener('click', async () => {
  if (!tab) return;
  $('save').disabled = true;
  const dup = await findByNorm(normalizeUrl(tab.url)); // SCN-003
  if (dup) { $('msg').className = 'msg dup'; $('msg').textContent = 'Already in your library — no duplicate made.'; return; }
  // Recognise straight from the tab (SCN-001): title is what the browser shows.
  const link = makeLink(toFullUrl(tab.url), { ok: !!tab.title, title: tab.title || '', description: '' }, Date.now());
  await putLink(link);
  $('msg').className = 'msg ok'; $('msg').textContent = '✓ Saved to My Links';
});

$('lib').addEventListener('click', () => chrome.runtime.openOptionsPage());

init();

