// Library UI.
// Slice 1 (SCN-001,002,003,004,022): save / recognise / list / open / dedupe.
// Slice 2 (SCN-005,006,007,019): edit in a pop-up, personal note (bold+bullets),
// labels with suggestions.

import {
  normalizeUrl, toFullUrl, hostOf, isProbablyUrl, makeLink,
  normalizeTag, addTag, suggestTags, sanitizeNote,
} from './src/core.js';
import { allLinks, putLink, findByNorm } from './src/db.js';

const $ = (id) => document.getElementById(id);
const input = $('url'), btn = $('save'), listEl = $('list'), countEl = $('count'),
  flash = $('flash'), backdrop = $('backdrop'), dialog = $('dialog');

let items = [];            // DB mirror, newest first
let editing = null;        // record being edited
let draftTags = [];        // tags while the editor is open

function newestFirst(a, b) { return (b.savedAt || 0) - (a.savedAt || 0); }
function allTags() { const s = new Set(); items.forEach((it) => (it.tags || []).forEach((t) => s.add(t))); return [...s].sort(); }
function favLetter(u) { return (hostOf(u)[0] || '•').toUpperCase(); }
function escapeHtml(s) { return String(s || '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c])); }
function escapeAttr(s) { return escapeHtml(s).replace(/"/g, '&quot;'); }

async function refresh(freshUrl, pulseNorm) {
  items = (await allLinks()).sort(newestFirst);
  render(freshUrl, pulseNorm);
}

function cardHtml(it, cls) {
  const titleLine = it.unreadable
    ? `${escapeHtml(hostOf(it.url))}<span class="ext">· couldn't read the page name</span>`
    : `${escapeHtml(it.title)}<span class="ext">↗ open</span>`;
  const desc = it.unreadable
    ? `<p class="desc faded">We couldn't read this page's name. It's saved and will still open — you can rename it.</p>`
    : (it.description ? `<p class="desc">${escapeHtml(it.description)}</p>` : '');
  const note = it.note ? `<div class="note"><span class="lbl">Note to self</span>${sanitizeNote(it.note)}</div>` : '';
  const tags = (it.tags && it.tags.length)
    ? `<div class="tags">${it.tags.map((t) => `<span class="tag">${escapeHtml(t)}</span>`).join('')}</div>` : '';
  return `<li class="card ${cls || ''}" data-id="${it.id}">
    <button class="editbtn" data-edit="${it.id}">✎ Edit</button>
    <p class="title">${titleLine}</p>${desc}${note}
    <div class="url"><span class="fav">${favLetter(it.url)}</span>${escapeHtml(hostOf(it.url))}</div>${tags}
  </li>`;
}

function render(freshUrl, pulseNorm, loadingUrl) {
  const rows = [];
  if (loadingUrl) {
    rows.push(`<li class="card fresh"><p class="loading">Reading the page to get its name…</p>
      <div class="url"><span class="fav">${favLetter(loadingUrl)}</span>${escapeHtml(hostOf(loadingUrl))}</div></li>`);
  }
  for (const it of items) {
    const cls = it.url === freshUrl ? 'fresh' : (it.norm === pulseNorm ? 'pulse' : '');
    rows.push(cardHtml(it, cls));
  }
  countEl.textContent = items.length ? `${items.length} link${items.length > 1 ? 's' : ''}` : '';
  listEl.innerHTML = items.length || loadingUrl
    ? rows.join('')
