  }
  const filtering = q || includes().length || excludes().length;
  countEl.textContent = items.length === 0 ? '' : (filtering ? `${shown.length} shown` : `${items.length} link${items.length > 1 ? 's' : ''}`);

  if (!items.length && !loadingUrl) {
    listEl.innerHTML = `<div class="empty"><div class="art">📚</div><h2>Your library starts here</h2>
