  } else if (!shown.length && !loadingUrl) {
    listEl.innerHTML = `<div class="empty">Nothing matches${q ? ' “' + escapeHtml(q) + '”' : ''}${filtering ? '' : ''}.<br>Try fewer words, or clear a topic.</div>`;
