}

function fetchMeta(url) {
  return new Promise((resolve) => {
    if (typeof chrome !== 'undefined' && chrome.runtime && chrome.runtime.sendMessage) {
      try { chrome.runtime.sendMessage({ type: 'fetchMeta', url: toFullUrl(url) }, (resp) => resolve(chrome.runtime.lastError || !resp ? { ok: false } : resp)); return; }
