  $('h').textContent = savable ? hostOf(tab.url) : '';
  $('save').disabled = !savable;
}

function showSaved(text, cls) {
  // Replace the button with a clear, persistent confirmation block.
  $('save').style.display = 'none';
  const done = $('done');
  done.className = 'done show ' + (cls || 'ok');
