python3 - <<'PY'
import re, os, sys
EXT="extension"
problems=[]

# ---- 1) every imported name is actually exported by its module ----
def exports_of(path):
    s=open(path).read()
    names=set()
    for m in re.finditer(r'export\s+(?:async\s+)?function\s+(\w+)', s): names.add(m.group(1))
    for m in re.finditer(r'export\s+(?:const|let|var)\s+(\w+)', s): names.add(m.group(1))
    for m in re.finditer(r'export\s*{([^}]+)}', s):
        for part in m.group(1).split(','):
            names.add(part.strip().split(' as ')[0].strip())
    return names

jsfiles=[]
for root,_,fs in os.walk(EXT):
    for f in fs:
        if f.endswith('.js'): jsfiles.append(os.path.join(root,f))

for jf in jsfiles:
    s=open(jf).read()
    for m in re.finditer(r'import\s*{([^}]+)}\s*from\s*[\'"]([^\'"]+)[\'"]', s):
        names=[n.strip().split(' as ')[0].strip() for n in m.group(1).split(',') if n.strip()]
        target=os.path.normpath(os.path.join(os.path.dirname(jf), m.group(2)))
        if not os.path.exists(target): problems.append(f"{jf}: import target missing {m.group(2)}"); continue
        exp=exports_of(target)
        for n in names:
            if n not in exp: problems.append(f"{jf}: imports '{n}' not exported by {m.group(2)}")

# ---- 2) element ids referenced via $()/getElementById exist in the paired HTML or in JS templates ----
pairs=[("library.js","library.html"),("popup.js","popup.html"),("viewer.js","viewer.html")]
for js,html in pairs:
    jsrc=open(os.path.join(EXT,js)).read()
    hsrc=open(os.path.join(EXT,html)).read()
    referenced=set(re.findall(r"\$\('([\w-]+)'\)", jsrc)) | set(re.findall(r"getElementById\('([\w-]+)'\)", jsrc))
    defined=set(re.findall(r'id="([\w-]+)"', hsrc)) | set(re.findall(r'id="([\w-]+)"', jsrc))
    missing=referenced - defined
    if missing: problems.append(f"{js}: id(s) referenced but never defined in {html} or JS templates: {sorted(missing)}")

# ---- 3) manifest files exist ----
man=open(os.path.join(EXT,"manifest.json")).read()
for m in re.finditer(r'"(service_worker|default_popup|page)"\s*:\s*"([^"]+)"', man):
    p=os.path.join(EXT,m.group(2))
    if not os.path.exists(p): problems.append(f"manifest references missing file {m.group(2)}")

if problems:
    print("WIRING PROBLEMS FOUND:"); [print(" -",p) for p in problems]; sys.exit(1)
print("Wiring audit clean: imports/exports consistent, element ids resolved, manifest files present.")
PY

